import{_ as a,o as t,c as o,ag as d}from"./chunks/framework.DaCm-iTo.js";const h=JSON.parse('{"title":"EmakiCodex","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/codex/index.md","filePath":"en/modules/codex/index.md","lastUpdated":null}'),n={name:"en/modules/codex/index.md"};function i(c,e,s,r,l,p){return t(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="emakicodex" tabindex="-1">EmakiCodex <a class="header-anchor" href="#emakicodex" aria-label="Permalink to &quot;EmakiCodex&quot;">​</a></h1><p>EmakiCodex is the vanilla-advancement codex module in the Emaki series. It defines advancement pages and nodes through <code>advancements/*.yml</code>, registers them as vanilla advancements, and lets commands, CoreLib actions, the public API, and gameplay triggers grant or revoke nodes.</p><p>When PacketEvents is installed, EmakiCodex can inject configured node coordinates into the client advancement tree and re-push the registered tree to online players. Without PacketEvents, advancements still register normally, but node placement is handled by the vanilla client parent tree and online players may need to reconnect after a reload to see the updated tree.</p><h2 id="basic-information" tabindex="-1">Basic information <a class="header-anchor" href="#basic-information" aria-label="Permalink to &quot;Basic information&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Module version</td><td><code>1.0.4</code></td></tr><tr><td>API Jar</td><td><code>emaki-codex-api-1.0.4.jar</code></td></tr><tr><td>Main class</td><td><code>emaki.jiuwu.craft.codex.EmakiCodexPlugin</code></td></tr><tr><td>Main command</td><td><code>/codex</code></td></tr><tr><td>Alias</td><td><code>/ecodex</code></td></tr><tr><td>Required dependency</td><td>EmakiCoreLib</td></tr><tr><td>Optional dependencies</td><td>PlaceholderAPI, PacketEvents, MythicMobs</td></tr><tr><td>Minimum server</td><td>Paper 1.21.8+ (<code>api-version: 1.21.8</code>, <code>folia-supported: true</code>)</td></tr><tr><td>Java</td><td>Java 25</td></tr><tr><td>Main permissions</td><td><code>emakicodex.use</code> (default true), <code>emakicodex.reload</code> (op), <code>emakicodex.debug</code> (op), <code>emakicodex.admin</code> (op)</td></tr></tbody></table><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./commands.html">Commands</a></td><td><code>/codex</code> and <code>/ecodex</code> subcommands, permissions, and examples.</td></tr><tr><td><a href="./configuration.html">Configuration</a></td><td>The global switches of <code>config.yml</code> and the <code>lang/*.yml</code> language files.</td></tr><tr><td><a href="./advancements.html">Advancements</a></td><td>The page and node fields of <code>advancements/*.yml</code>, node key rules, coordinate rules, and completion actions.</td></tr><tr><td><a href="./triggers.html">Triggers</a></td><td>How to write <code>triggers.entries</code>, the available trigger variables, and condition examples.</td></tr><tr><td><a href="./corelib-actions.html">CoreLib Actions</a></td><td>Actions registered by EmakiCodex into CoreLib&#39;s ActionRegistry.</td></tr><tr><td><a href="./api.html">API</a></td><td>How third-party plugins call Codex through <code>emaki-codex-api</code>.</td></tr></tbody></table><h2 id="core-features" tabindex="-1">Core features <a class="header-anchor" href="#core-features" aria-label="Permalink to &quot;Core features&quot;">​</a></h2><ul><li><strong>Vanilla advancement codex</strong>: each <code>advancements/*.yml</code> file is one vanilla advancement tab, with node keys like <code>emakicodex:&lt;page&gt;/&lt;node&gt;</code>.</li><li><strong>Manual grant and revoke</strong>: administrators can manage online player progress with <code>/codex grant</code> and <code>/codex revoke</code>.</li><li><strong>Action-based grants</strong>: other plugins can call Codex actions such as <code>codex_grant_advancement</code>, <code>codex_revoke_advancement</code>, and <code>codex_reset_page</code> from CoreLib action chains.</li><li><strong>Gameplay triggers</strong>: nodes can define <code>triggers.entries</code> for kills, crafting, furnace extraction, fishing, brewing, taming, block breaking, mature crop harvesting, and related CoreLib gameplay events.</li><li><strong>Completion actions</strong>: when a node completes, <code>actions.complete</code> can run CoreLib actions such as messages, rewards, or cross-module logic.</li><li><strong>PacketEvents coordinate channel</strong>: when PacketEvents is installed and <code>advancement.packet-coordinates</code> is enabled, node <code>x</code> / <code>y</code> values are sent to the client advancement screen.</li></ul><h2 id="file-layout" tabindex="-1">File layout <a class="header-anchor" href="#file-layout" aria-label="Permalink to &quot;File layout&quot;">​</a></h2><p>After startup, EmakiCodex mainly uses these files:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/EmakiCodex/</span></span>
<span class="line"><span>├─ config.yml</span></span>
<span class="line"><span>├─ advancements/</span></span>
<span class="line"><span>│  └─ example_page.yml</span></span>
<span class="line"><span>└─ lang/</span></span>
<span class="line"><span>   ├─ zh_CN.yml</span></span>
<span class="line"><span>   └─ en_US.yml</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>config.yml</code></td><td>Main settings for default resource release, advancement registration, PacketEvents coordinates, and trigger enablement.</td></tr><tr><td><code>advancements/*.yml</code></td><td>Advancement pages. Each file defines one page, one root node, and any number of child nodes.</td></tr><tr><td><code>lang/*.yml</code></td><td>Command, reload, and console messages.</td></tr></tbody></table><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><ol><li>Put <code>EmakiCoreLib-*.jar</code> and <code>EmakiCodex-*.jar</code> into the server <code>plugins/</code> directory.</li><li>Do not put <code>emaki-codex-api-*.jar</code> into <code>plugins/</code>; the API Jar is only for developer compile dependencies.</li><li>After first startup, inspect <code>plugins/EmakiCodex/advancements/example_page.yml</code>.</li><li>After editing or adding pages, run:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/codex reload</span></span></code></pre></div><ol start="5"><li>Grant the sample node for testing:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/codex grant Steve example/first_step</span></span></code></pre></div><p>The full key form also works:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/codex grant Steve emakicodex:example/first_step</span></span></code></pre></div><h2 id="advancement-page-quick-view" tabindex="-1">Advancement page quick view <a class="header-anchor" href="#advancement-page-quick-view" aria-label="Permalink to &quot;Advancement page quick view&quot;">​</a></h2><p>One <code>advancements/*.yml</code> file defines one advancement page:</p><ul><li>Page level: <code>page_id</code> (the key path prefix), <code>title</code>, <code>background</code>, <code>root</code>.</li><li>Node level: <code>icon</code>, <code>title</code>, <code>description</code>, <code>frame</code>, <code>parent</code>, <code>x</code> / <code>y</code>, <code>toast</code>, <code>announce</code>, <code>hidden</code>.</li><li>Node completion actions go in <code>actions.complete</code>, gameplay triggers in <code>triggers.entries</code>. Trigger conditions use CoreLib condition groups with <code>condition.type</code> and <code>condition.entries</code>.</li></ul><p>Nodes register as <code>emakicodex:&lt;page_id&gt;/&lt;node_id&gt;</code>. See <a href="./advancements.html">Advancements</a> for the full field tables, key rules, and coordinate rules, and <a href="./triggers.html">Triggers</a> for trigger variables and condition examples.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>EmakiCodex currently focuses on vanilla advancement codex features and no longer provides recipe/JEI transfer features.</li><li>Nodes are completed through Codex grants: commands, actions, the public API, or triggers award the internal <code>codex</code> criterion.</li><li><code>actions.complete</code> only runs on the first completion; granting an already completed node does not repeat completion actions.</li><li>If coordinates are enabled, configure <code>x</code> / <code>y</code> for every node in a page to avoid mixing explicit coordinates with client auto-layout.</li></ul>`,26)])])}const g=a(n,[["render",i]]);export{h as __pageData,g as default};
